class Solution:
    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:
        line = [x for num, start, end in trips for x in [[start, num], [end, -num]]]
        line.sort()
        for _, num in line:
            capacity -= num
            if capacity < 0:
                return False
        return True

